WITH flattened AS (SELECT id, created_at, coupon_codes, line.product_id, line.price, line.promo FROM carts LATERAL VIEW OUTER EXPLODE(items) li AS line), valid AS (SELECT *, FLOOR(product_id) AS product_id_whole, COALESCE(promo, 'UNKNOWN') AS promo_clean FROM flattened WHERE created_at >= DATE '2025-03-01' AND created_at < '2025-05-27'), metrics AS (SELECT *, CUME_DIST() OVER (ORDER BY product_id_whole NULLS FIRST) AS product_id_whole_cume_dist, CUME_DIST() OVER (PARTITION BY promo ORDER BY price DESC NULLS FIRST) AS price_cume_dist, COUNT(price) OVER (PARTITION BY promo) AS promo_count_price FROM valid), metrics_carts AS (SELECT *, ROUND(promo_count_price / SUM(promo_count_price) OVER (PARTITION BY promo), 4) AS promo_count_price_share, MIN(price_cume_dist) OVER (PARTITION BY promo) AS promo_min_price_cume_dist FROM metrics), with_windows AS (SELECT *, COUNT(product_id_whole_cume_dist) OVER (PARTITION BY promo ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) AS product_id_whole_cume_dist_count_30m, RANK() OVER (PARTITION BY promo ORDER BY promo_count_price NULLS FIRST) AS promo_count_price_rank, MAX(product_id) OVER (PARTITION BY promo) AS promo_max_product_id FROM metrics_carts) SELECT product_id, CASE WHEN promo_count_price >= 15 THEN 'PREMIUM' ELSE 'STANDARD' END AS promo_count_price_tier, SUM(promo_count_price_rank) FILTER (WHERE promo = 'VIP') AS vip_total_promo_count_price_rank, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes, MAX(created_at) AS ended_at, PERCENTILE_APPROX(price, ARRAY(0.25, 0.5, 0.75)) AS price_quartiles, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min_2 FROM with_windows GROUP BY ROLLUP (product_id, CASE WHEN promo_count_price >= 15 THEN 'PREMIUM' ELSE 'STANDARD' END);
